1	'use client';
2	
3	import { useState, useRef, useEffect } from "react";
4	import { motion } from "framer-motion";
5	import { Copy, Check } from "lucide-react";
6	import { Card, CardContent } from "@/components/ui/card";
7	import { Badge } from "@/components/ui/badge";
8	import { cn } from "@/lib/utils";
9	import type { CopyRewrite, CopyRewriteElementType } from "@/types";
10	
11	// ── Element type label + color map ────────────────────────────
12	
13	const ELEMENT_TYPE_CONFIG: Record<
14	  CopyRewriteElementType,
15	  { label: string; className: string }
16	> = {
17	  headline: {
18	    label: "Headline",
19	    className: "bg-violet-100 text-violet-700 border-violet-200",
20	  },
21	  subheadline: {
22	    label: "Subheadline",
23	    className: "bg-indigo-100 text-indigo-700 border-indigo-200",
24	  },
25	  cta: {
26	    label: "CTA",
27	    className: "bg-orange-100 text-orange-700 border-orange-200",
28	  },
29	  value_prop: {
30	    label: "Value Prop",
31	    className: "bg-blue-100 text-blue-700 border-blue-200",
32	  },
33	  body_copy: {
34	    label: "Body Copy",
35	    className: "bg-muted text-foreground border-border",
36	  },
37	};
38	
39	// ── Copy inline button ─────────────────────────────────────────
40	
41	function CopyInline({ text }: { text: string }) {
42	  const [copied, setCopied] = useState(false);
43	  const timerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
44	
45	  useEffect(
46	    () => () => {
47	      if (timerRef.current) clearTimeout(timerRef.current);
48	    },
49	    [],
50	  );
51	
52	  const handleCopy = async () => {
53	    if (timerRef.current) clearTimeout(timerRef.current);
54	    try {
55	      await navigator.clipboard.writeText(text);
56	    } catch {
57	      /* clipboard API unavailable */
58	    }
59	    setCopied(true);
60	    timerRef.current = setTimeout(() => setCopied(false), 2000);
61	  };
62	
63	  return (
64	    <button
65	      onClick={() => void handleCopy()}
66	      className={cn(
67	        "inline-flex items-center gap-1 rounded-md px-2 py-0.5 text-2xs font-medium border transition-all",
68	        copied
69	          ? "bg-green-50 text-green-600 border-green-200"
70	          : "bg-card text-muted-foreground border-border/50 hover:bg-muted/40 hover:text-foreground",
71	      )}
72	    >
73	      {copied ? (
74	        <>
75	          <Check className="h-2.5 w-2.5" />
76	          Copied
77	        </>
78	      ) : (
79	        <>
80	          <Copy className="h-2.5 w-2.5" />
81	          Copy
82	        </>
83	      )}
84	    </button>
85	  );
86	}
87	
88	// ── CopyRewriteCard ────────────────────────────────────────────
89	
90	interface CopyRewriteCardProps {
91	  rewrite: CopyRewrite;
92	}
93	
94	export function CopyRewriteCard({ rewrite }: CopyRewriteCardProps) {
95	  const typeConfig =
96	    ELEMENT_TYPE_CONFIG[rewrite.element_type] ?? ELEMENT_TYPE_CONFIG.body_copy;
97	
98	  return (
99	    <motion.div
100	      initial={{ opacity: 0, y: 8 }}
101	      animate={{ opacity: 1, y: 0 }}
102	      transition={{ duration: 0.25, ease: "easeOut" }}
103	    >
104	      <Card className="border-border/50 shadow-xs overflow-hidden">
105	        <CardContent className="p-0">
106	          {/* Element type badge row */}
107	          <div className="flex items-center gap-2 border-b border-border/40 px-4 py-2.5">
108	            <Badge
109	              variant="outline"
110	              className={cn("text-2xs font-semibold uppercase tracking-wide px-2 py-0.5", typeConfig.className)}
111	            >
112	              {typeConfig.label}
113	            </Badge>
114	            {rewrite.impact && (
115	              <span className="text-xs text-muted-foreground ml-auto truncate max-w-[280px]">
116	                {rewrite.impact}
117	              </span>
118	            )}
119	          </div>
120	
121	          {/* Side-by-side copy comparison */}
122	          <div className="grid grid-cols-1 gap-0 sm:grid-cols-2">
123	            {/* Current copy */}
124	            <div className="border-b border-border/40 p-4 sm:border-b-0 sm:border-r">
125	              <p className="mb-2 text-2xs font-semibold uppercase tracking-widest text-red-500">
126	                Current
127	              </p>
128	              <div className="rounded-lg bg-red-50 border border-red-100 p-3">
129	                <p className="text-sm text-slate-600 leading-relaxed line-through decoration-red-400/60">
130	                  {rewrite.original}
131	                </p>
132	              </div>
133	            </div>
134	
135	            {/* Suggested copy */}
136	            <div className="p-4">
137	              <div className="mb-2 flex items-center justify-between">
138	                <p className="text-2xs font-semibold uppercase tracking-widest text-emerald-600">
139	                  Suggested
140	                </p>
141	                <CopyInline text={rewrite.suggested} />
142	              </div>
143	              <div className="rounded-lg bg-emerald-50 border border-emerald-100 p-3">
144	                <p className="text-sm text-slate-700 font-medium leading-relaxed">
145	                  {rewrite.suggested}
146	                </p>
147	              </div>
148	            </div>
149	          </div>
150	
151	          {/* Reasoning */}
152	          <div className="border-t border-border/40 px-4 py-3">
153	            <p className="text-xs text-muted-foreground leading-relaxed">
154	              <span className="font-semibold text-foreground/70">Why this works: </span>
155	              {rewrite.reasoning}
156	            </p>
157	          </div>
158	        </CardContent>
159	      </Card>
160	    </motion.div>
161	  );
162	}
