142	function CopyButton({ text }: { text: string }) {
143	  const [copied, setCopied] = useState(false);
144	  const timerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
145	
146	  useEffect(() => () => { if (timerRef.current) clearTimeout(timerRef.current); }, []);
147	
148	  const handleCopy = async () => {
149	    if (timerRef.current) clearTimeout(timerRef.current);
150	    try {
151	      await navigator.clipboard.writeText(text);
152	    } catch {
153	      const textarea = document.createElement("textarea");
154	      textarea.value = text;
155	      document.body.appendChild(textarea);
156	      textarea.select();
157	      document.execCommand("copy");
158	      document.body.removeChild(textarea);
159	    }
160	    setCopied(true);
161	    timerRef.current = setTimeout(() => setCopied(false), 2000);
162	  };
163	
164	  return (
165	    <TooltipProvider delayDuration={200}>
166	      <Tooltip>
167	        <TooltipTrigger asChild>
168	          <button
169	            onClick={() => void handleCopy()}
170	            className={cn(
171	              "inline-flex items-center gap-1 rounded-md px-2 py-1 text-xs font-medium transition-all",
172	              copied
173	                ? "bg-green-50 text-green-600 border border-green-200"
174	                : "bg-card/80 text-slate-500 border border-border/50 hover:bg-muted/40 hover:text-foreground"
175	            )}
176	          >
177	            {copied ? (
178	              <><Check className="h-3 w-3" />Copied</>
179	            ) : (
180	              <><Copy className="h-3 w-3" />Copy</>
181	            )}
182	          </button>
183	        </TooltipTrigger>
184	        <TooltipContent side="top">
185	          <p>{copied ? "Copied to clipboard!" : "Copy AI suggestion"}</p>
186	        </TooltipContent>
187	      </Tooltip>
188	    </TooltipProvider>
189	  );
190	}
