259	// ── Pillar Bar with Benchmark ───────────────────────────────────
260	
261	function PillarBarWithBenchmark({
262	  pillar,
263	  score,
264	  benchmark,
265	}: {
266	  pillar: string;
267	  score: number;
268	  benchmark: number;
269	}) {
270	  const config = CRO_PILLARS.find((p) => p.key === pillar);
271	  if (!config) return null;
272	
273	  const Icon = config.icon;
274	  const diff = score - benchmark;
275	  const diffLabel = diff >= 0 ? `+${diff}` : `${diff}`;
276	  const diffColor = diff >= 0 ? "text-green-600" : "text-red-500";
277	
278	  return (
279	    <div className="group">
280	      <div className="flex items-center gap-3">
281	        <Icon className="h-4 w-4 shrink-0 text-muted-foreground" />
282	        <span className="w-36 shrink-0 truncate text-sm text-foreground/80">{config.label}</span>
283	        <div className="relative flex-1">
284	          <div className="h-2.5 w-full overflow-hidden rounded-full bg-muted/50">
285	            <div
286	              className={cn("h-full rounded-full transition-all duration-1000 ease-out", getScoreBgColor(score))}
287	              style={{ width: `${score}%` }}
288	            />
289	          </div>
290	          <TooltipProvider delayDuration={100}>
291	            <Tooltip>
292	              <TooltipTrigger asChild>
293	                <div
294	                  className="absolute top-1/2 -translate-y-1/2 h-5 w-0.5 bg-foreground/20 rounded-full"
295	                  style={{ left: `${benchmark}%` }}
296	                >
297	                  <div className="absolute -top-1 left-1/2 -translate-x-1/2 h-1.5 w-1.5 rounded-full bg-foreground/30" />
298	                </div>
299	              </TooltipTrigger>
300	              <TooltipContent side="top" className="text-xs">
301	                <p>Industry avg: {benchmark}/100</p>
302	              </TooltipContent>
303	            </Tooltip>
304	          </TooltipProvider>
305	        </div>
306	        <span className={cn("w-10 text-right text-sm font-semibold", getScoreColor(score))}>
307	          {formatScore(score)}
308	        </span>
309	        <span className={cn("w-12 text-right text-xs font-medium", diffColor)}>
310	          {diffLabel} avg
311	        </span>
312	      </div>
313	    </div>
314	  );
