343	export default function AuditReportPage() {
344	  const params = useParams<{ id: string }>();
345	  const id = params.id;
346	  const router = useRouter();
347	  const [pdfDialogOpen, setPdfDialogOpen] = useState(false);
348	  const pdfExportEnabled = useFeatureFlag("pdf_export_enabled", false);
349	  const [linkCopied, setLinkCopied] = useState(false);
350	  const [shareModalOpen, setShareModalOpen] = useState(false);
351	  const [selectedIndustry, setSelectedIndustry] = useState<IndustryType>("saas");
352	  const linkCopyTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
353	  useEffect(() => () => { if (linkCopyTimerRef.current) clearTimeout(linkCopyTimerRef.current); }, []);
354	
355	  const generateShareLink = useGenerateShareLink();
356	  const revokeShareLink = useRevokeShareLink();
357	
358	  const { profile } = useAuth();
359	  const { data: scan, isLoading: scanLoading, error: scanError } = useScan(id);
360	  const { data: pillarResults = [], isLoading: resultsLoading } = useScanResults(id);
361	  const { data: fixedData } = useFixedFindings(id);
362	  const toggleFixed = useToggleFindingFixed();
363	  const refreshScan = useRefreshScan();
364	
365	  const urlHash = scan?.url ? scan.url.toLowerCase().trim() : "";
366	  const { data: comparison } = useScanComparison(scan?.id, scan?.url);
367	  const { data: historyEntries = [] } = useScanHistory(urlHash);
368	
369	  const historyChartData = historyEntries.map((e) => ({
370	    date: e.scanned_at,
371	    score: e.score,
372	  }));
373	
374	  const { data: industryBenchmarks = {} } = useIndustryBenchmarks(
375	    selectedIndustry,
376	    scan?.page_type ?? "landing"
377	  );
378	
379	  const { isConnected: ga4Connected } = useGa4Connection();
380	
381	  const isLoading = scanLoading || resultsLoading;
382	
383	  if (isLoading) {
384	    return (
385	      <PageTransition>
386	        <AuditReportSkeleton />
387	      </PageTransition>
388	    );
389	  }
390	
391	  if (scanError || !scan) {
392	    return (
393	      <PageTransition>
394	        <div className="flex flex-col items-center justify-center py-20 text-center">
395	          <div className="mb-4 flex h-16 w-16 items-center justify-center rounded-lg bg-muted/50">
396	            <AlertCircle className="h-8 w-8 text-muted-foreground" />
397	          </div>
398	          <h2 className="text-xl font-bold text-foreground">Report not found</h2>
399	          <p className="mt-2 max-w-sm text-sm text-muted-foreground">
400	            This scan may have been deleted or hasn&apos;t finished processing yet.
401	          </p>
402	          <div className="mt-6 flex gap-3">
403	            <Button variant="outline" asChild>
404	              <Link href="/reports">View All Reports</Link>
405	            </Button>
406	            <Button asChild>
407	              <Link href="/scan">Run New Scan</Link>
408	            </Button>
409	          </div>
410	        </div>
411	      </PageTransition>
412	    );
413	  }
414	
415	  const sortedPillars = [...pillarResults].sort((a, b) => a.score - b.score);
416	
417	  const allFindings = pillarResults.flatMap((p) => p.findings);
418	  const totalFindings = allFindings.length;
419	  const criticalCount = allFindings.filter((f) => f.severity === "critical").length;
420	  const quickWinCount = allFindings.filter((f) => f.effort === "quick" && f.severity !== "passed").length;
421	  const lockedFindings = allFindings.filter((f) => f.is_premium).length;
422	
423	  const estimatedTotalLift = allFindings.reduce((sum, f) => {
424	    const match = f.estimated_lift.match(/(\d+(?:\.\d+)?)-?(\d+(?:\.\d+)?)?%/);
425	    if (match?.[1]) {
426	      const low = parseFloat(match[1]);
