18	function truncateUrl(url: string, max = 48): string {
19	  try {
20	    const u = new URL(url);
21	    const display = u.hostname + u.pathname;
22	    return display.length > max ? display.slice(0, max) + "\u2026" : display;
23	  } catch {
24	    return url.length > max ? url.slice(0, max) + "\u2026" : url;
25	  }
26	}
