28	// ── Delta Badge ───────────────────────────────────────────────────
29	
30	function DeltaChip({ delta }: { delta: number }) {
31	  if (delta === 0) {
32	    return (
33	      <span className="inline-flex items-center gap-0.5 rounded-full bg-muted px-2 py-0.5 text-xs font-semibold text-muted-foreground">
34	        <Minus className="h-3 w-3" />
35	        No change
36	      </span>
37	    );
38	  }
39	  const isUp = delta > 0;
40	  return (
41	    <span
42	      className={cn(
43	        "inline-flex items-center gap-0.5 rounded-full px-2 py-0.5 text-xs font-bold",
44	        isUp ? "bg-green-100 text-green-700" : "bg-red-100 text-red-600"
45	      )}
46	    >
47	      {isUp ? <TrendingUp className="h-3 w-3" /> : <TrendingDown className="h-3 w-3" />}
48	      {isUp ? `+${delta}` : delta} pts
49	    </span>
50	  );
51	}
