759	export default function IntegrationsPage() {
760	  const [dialogProvider, setDialogProvider] =
761	    useState<IntegrationProvider | null>(null);
762	
763	  const { profile } = useAuth();
764	  const { data: integrations = [], isLoading, isError, refetch } = useIntegrations();
765	
766	  const isPro = profile ? isProPlus(profile.plan) : false;
767	  const slackConnected = integrations.some(
768	    (i) => i.provider === "slack" && i.is_active,
769	  );
770	  const ga4Connected = integrations.some(
771	    (i) => i.provider === "google_analytics" && i.is_active,
772	  );
773	  const connectedCount = integrations.filter((i) => i.is_active).length;
774	  const total = INTEGRATIONS.length + 2;
775	
776	  const activeDialog = INTEGRATIONS.find((c) => c.id === dialogProvider) ?? null;
777	
778	  // Show toast if OAuth redirected back with result query params
779	  useEffect(() => {
780	    if (typeof window === "undefined") return;
781	    const params = new URLSearchParams(window.location.search);
782	    const cleanUrl = window.location.pathname;
783	
784	    const slackParam = params.get("slack");
785	    if (slackParam === "connected") {
786	      toast.success("Slack connected successfully");
787	      window.history.replaceState(null, "", cleanUrl);
788	    } else if (slackParam === "error") {
789	      toast.error("Failed to connect Slack. Please try again.");
790	      window.history.replaceState(null, "", cleanUrl);
791	    }
792	
793	    const ga4Param = params.get("ga4");
794	    if (ga4Param === "connected") {
795	      toast.success("Google Analytics 4 connected successfully");
796	      window.history.replaceState(null, "", cleanUrl);
797	    } else if (ga4Param === "error") {
798	      toast.error("Failed to connect Google Analytics. Please try again.");
799	      window.history.replaceState(null, "", cleanUrl);
800	    }
801	  }, []);
802	
803	  return (
804	    <PageTransition>
805	      <div className="space-y-6">
806	        <div className="flex items-start justify-between gap-4">
807	          <PageHeader
808	            title="Integrations"
809	            description="Connect your analytics tools for deeper CRO insights"
810	          />
811	          {!isLoading && (
812	            <div className="flex shrink-0 items-center gap-1.5 text-sm text-muted-foreground pt-1">
813	              <span className="font-medium text-foreground">
814	                {connectedCount}
815	              </span>{" "}
816	              of {total} integrations connected
817	            </div>
818	          )}
819	        </div>
820	
821	        {isLoading ? (
822	          <IntegrationsSkeleton />
823	        ) : isError ? (
824	          <ErrorState
825	            title="Failed to load integrations"
826	            description="There was a problem fetching your integrations. Check your connection and try again."
827	            onRetry={() => void refetch()}
828	          />
829	        ) : (
830	          <div className="grid grid-cols-1 gap-4 md:grid-cols-2">
831	            <Ga4IntegrationCard
832	              isConnected={ga4Connected}
833	              isPro={isPro}
834	              userId={profile?.id ?? ""}
835	            />
836	            {INTEGRATIONS.map((config) => {
837	              const connected = integrations.find(
838	                (i) => i.provider === config.id && i.is_active
839	              );
840	              return (
841	                <IntegrationCard
842	                  key={config.id}
843	                  config={config}
844	                  isConnected={!!connected}
845	                  onConnectRequest={() => setDialogProvider(config.id)}
846	                />
847	              );
848	            })}
849	            <SlackIntegrationCard
850	              isConnected={slackConnected}
851	              isPro={isPro}
852	              userId={profile?.id ?? ""}
853	            />
854	          </div>
855	        )}
856	
857	        {activeDialog && (
858	          <ConnectDialog
859	            config={activeDialog}
860	            open={dialogProvider !== null}
861	            onOpenChange={(open) => {
862	              if (!open) setDialogProvider(null);
863	            }}
864	          />
865	        )}
866	
867	        <Separator />
868	        <WebhookManager />
869	      </div>
870	    </PageTransition>
871	  );
872	}
