81	              <AlertTriangle className="h-4 w-4 shrink-0 text-amber-600 mt-0.5" />
82	              <p className="text-sm text-amber-800">
83	                Save this key now — it will not be shown again.
84	              </p>
85	            </div>
86	
87	            <div className="space-y-2">
88	              <Label>Your API Key</Label>
89	              <div className="flex gap-2">
90	                <code className="flex-1 overflow-auto rounded-md border bg-muted px-3 py-2 font-mono text-sm break-all">
91	                  {generatedKey}
92	                </code>
93	                <Button
94	                  type="button"
95	                  variant="outline"
96	                  size="icon"
97	                  onClick={() => void handleCopy()}
98	                  aria-label="Copy API key"
99	                >
100	                  {copied ? (
101	                    <Check className="h-4 w-4 text-green-600" />
102	                  ) : (
103	                    <Copy className="h-4 w-4" />
104	                  )}
105	                </Button>
106	              </div>
107	            </div>
108	          </div>
109	        )}
110	
111	        <DialogFooter>
112	          {!generatedKey ? (
113	            <>
114	              <Button variant="outline" onClick={handleClose} disabled={isPending}>
