3	import { useState, useRef, useEffect } from "react";
4	import { Link2, Twitter, Linkedin, Check, ScanLine } from "lucide-react";
5	import {
6	  Dialog,
7	  DialogContent,
8	  DialogHeader,
9	  DialogTitle,
10	} from "@/components/ui/dialog";
11	import { Button } from "@/components/ui/button";
12	import { toast } from "sonner";
13	import { getScoreHex, getScoreLabel } from "@/lib/score-utils";
14	
15	interface ShareScoreModalProps {
16	  open: boolean;
17	  onOpenChange: (open: boolean) => void;
18	  score: number;
19	  url: string;
20	  reportUrl?: string;
21	}
22	
23	export function ShareScoreModal({
24	  open,
25	  onOpenChange,
26	  score,
27	  url,
28	  reportUrl,
29	}: ShareScoreModalProps) {
30	  const [linkCopied, setLinkCopied] = useState(false);
31	  const timerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
32	
33	  useEffect(() => () => { if (timerRef.current) clearTimeout(timerRef.current); }, []);
34	
35	  const scoreColor = getScoreHex(score);
36	  const scoreLabel = getScoreLabel(score);
37	  const shareUrl = reportUrl ?? (typeof window !== "undefined" ? window.location.href : "");
38	
39	  let hostname = url;
40	  try { hostname = new URL(url).hostname.replace("www.", ""); } catch { /* keep raw */ }
41	
42	  // Circumference math for the ring
43	  const size = 120;
44	  const strokeWidth = 10;
45	  const radius = (size - strokeWidth) / 2;
46	  const circumference = 2 * Math.PI * radius;
47	  const offset = circumference * (1 - score / 100);
48	
49	  const handleCopyLink = async () => {
50	    if (timerRef.current) clearTimeout(timerRef.current);
51	    try {
52	      await navigator.clipboard.writeText(shareUrl);
53	    } catch {
54	      const textarea = document.createElement("textarea");
55	      textarea.value = shareUrl;
56	      document.body.appendChild(textarea);
57	      textarea.select();
58	      document.execCommand("copy");
59	      document.body.removeChild(textarea);
60	    }
61	    setLinkCopied(true);
62	    toast.success("Report link copied to clipboard!");
63	    timerRef.current = setTimeout(() => setLinkCopied(false), 2500);
64	  };
65	
66	  const handleTwitter = () => {
67	    const text = encodeURIComponent(
68	      `I just audited ${hostname} with @ConvertScan and got a CRO score of ${score}/100.\n\nFind out your conversion score — it's free:`
69	    );
70	    const encodedUrl = encodeURIComponent(shareUrl);
71	    window.open(
72	      `https://twitter.com/intent/tweet?text=${text}&url=${encodedUrl}`,
73	      "_blank",
74	      "noopener,noreferrer"
75	    );
76	  };
77	
78	  const handleLinkedIn = () => {
79	    const encodedUrl = encodeURIComponent(shareUrl);
80	    window.open(
81	      `https://www.linkedin.com/sharing/share-offsite/?url=${encodedUrl}`,
82	      "_blank",
83	      "noopener,noreferrer"
84	    );
85	  };
86	
87	  return (
88	    <Dialog open={open} onOpenChange={onOpenChange}>
89	      <DialogContent className="max-w-sm gap-0 p-0 overflow-hidden">
90	        <DialogHeader className="sr-only">
91	          <DialogTitle>Share your CRO score</DialogTitle>
92	        </DialogHeader>
93	
94	        {/* Score card preview — dark branded */}
95	        <div className="bg-[#0F172A] px-8 py-10 text-center">
96	          {/* Logo */}
97	          <div className="mb-6 flex items-center justify-center gap-2">
98	            <div className="flex h-6 w-6 items-center justify-center rounded-md bg-indigo-500">
99	              <ScanLine className="h-3 w-3 text-white" />
100	            </div>
101	            <span className="text-sm font-semibold text-white/80 tracking-wide">ConvertScan</span>
102	          </div>
103	
104	          {/* Score ring */}
105	          <div className="relative mx-auto mb-4 inline-flex items-center justify-center">
106	            <svg width={size} height={size} className="-rotate-90">
107	              <circle
108	                cx={size / 2}
109	                cy={size / 2}
110	                r={radius}
111	                fill="none"
112	                stroke="rgba(255,255,255,0.08)"
113	                strokeWidth={strokeWidth}
114	              />
115	              <circle
116	                cx={size / 2}
117	                cy={size / 2}
118	                r={radius}
119	                fill="none"
120	                stroke={scoreColor}
121	                strokeWidth={strokeWidth}
122	                strokeLinecap="round"
123	                strokeDasharray={circumference}
124	                strokeDashoffset={offset}
125	                style={{ transition: "stroke-dashoffset 0.8s ease-out" }}
126	              />
127	            </svg>
128	            <div className="absolute inset-0 flex flex-col items-center justify-center">
129	              <span className="text-3xl font-bold text-white tabular-nums leading-none">
130	                {score}
131	              </span>
132	              <span className="text-xs text-white/50">/100</span>
133	            </div>
134	          </div>
135	
136	          {/* Score label */}
137	          <p className="text-sm font-semibold" style={{ color: scoreColor }}>
138	            {scoreLabel}
139	          </p>
140	
141	          {/* Audited URL */}
142	          <p className="mt-2 text-xs text-white/40 truncate">{hostname}</p>
143	
144	          {/* Bottom branding */}
145	          <p className="mt-6 text-xs text-white/30">
146	            Get your CRO score at convertscan.ai
147	          </p>
148	        </div>
149	
150	        {/* Share actions */}
151	        <div className="space-y-3 p-5">
152	          <p className="text-center text-sm font-medium text-foreground">Share your score</p>
153	
154	          <Button
155	            className="w-full bg-[#1DA1F2] text-white hover:bg-[#1a8fd4]"
156	            onClick={handleTwitter}
157	          >
158	            <Twitter className="mr-2 h-4 w-4" />
159	            Share on X / Twitter
160	          </Button>
161	
162	          <Button
163	            className="w-full bg-[#0A66C2] text-white hover:bg-[#0958aa]"
164	            onClick={handleLinkedIn}
165	          >
166	            <Linkedin className="mr-2 h-4 w-4" />
167	            Share on LinkedIn
168	          </Button>
169	
170	          <Button
171	            variant="outline"
172	            className="w-full border-border/50"
173	            onClick={() => void handleCopyLink()}
174	          >
175	            {linkCopied ? (
176	              <><Check className="mr-2 h-4 w-4 text-green-600" />Link Copied!</>
177	            ) : (
178	              <><Link2 className="mr-2 h-4 w-4" />Copy Report Link</>
179	            )}
180	          </Button>
181	        </div>
182	      </DialogContent>
183	    </Dialog>
184	  );
185	}
